/**
 * @author Arjohn Kampman
 */
public class IterativeEvaluationOptimizer implements QueryOptimizer {

	public IterativeEvaluationOptimizer() {
	}

	@Override
	public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(tupleExpr, bindings);
		tupleExpr.visit(new IEOVisitor(analysis));
	}

	private static class IEOVisitor extends AbstractSimpleQueryModelVisitor<RuntimeException> {

		private final QueryAlgebraBindingAnalysis analysis;

		IEOVisitor(QueryAlgebraBindingAnalysis analysis) {
			super(false);
			this.analysis = analysis;
		}

		@Override
		public void meet(Union union) {
			super.meet(union);

			TupleExpr leftArg = union.getLeftArg();
			TupleExpr rightArg = union.getRightArg();

			if (leftArg instanceof Join leftJoinArg && rightArg instanceof Join rightJoin) {

				TupleExpr leftCommon = leftJoinArg.getLeftArg();
				TupleExpr rightCommon = rightJoin.getLeftArg();

				if (canFactor(leftCommon, rightCommon, union)) {
					// factor out the left-most join argument
					Join newJoin = new Join();
					union.replaceWith(newJoin);
					newJoin.setLeftArg(leftCommon);
					newJoin.setRightArg(union);
					union.setLeftArg(leftJoinArg.getRightArg());
					union.setRightArg(rightJoin.getRightArg());

					analysis.invalidate();
					union.visit(this);
				}
			}
		}

		private boolean canFactor(TupleExpr leftCommon, TupleExpr rightCommon, Union union) {
			if (!leftCommon.equals(rightCommon) || !AlgebraEvaluationSafety.isRepeatable(leftCommon)) {
				return false;
			}

			QueryAlgebraBindingAnalysis.ReadOnlyContext leftContext = analysis.contextAt(leftCommon);
			QueryAlgebraBindingAnalysis.ReadOnlyContext rightContext = analysis.contextAt(rightCommon);
			QueryAlgebraBindingAnalysis.ReadOnlyContext destinationContext = analysis.contextForInsertedJoin(union);
			QueryAlgebraBindingAnalysis.OutputFacts leftFacts = analysis.outputFacts(leftCommon, leftContext);
			QueryAlgebraBindingAnalysis.OutputFacts rightFacts = analysis.outputFacts(rightCommon, rightContext);
			QueryAlgebraBindingAnalysis.OutputFacts destinationFacts = analysis.outputFacts(leftCommon,
					destinationContext);
			Set<String> relevantNames = new HashSet<>(VarNameCollector.process(leftCommon));
			relevantNames.addAll(leftContext.visibleNames());
			relevantNames.addAll(rightContext.visibleNames());
			relevantNames.addAll(destinationContext.visibleNames());
			addOutputNames(relevantNames, leftFacts);
			addOutputNames(relevantNames, rightFacts);
			addOutputNames(relevantNames, destinationFacts);
			boolean equivalentBranchInputs = analysis.bindingFactsEquivalent(relevantNames, leftContext, rightContext)
					&& equivalentFacts(leftFacts, rightFacts);
			if (!equivalentBranchInputs) {
				return false;
			}

			boolean equivalentDestinationInput = analysis.bindingFactsEquivalent(relevantNames, leftContext,
					destinationContext)
					&& equivalentFacts(leftFacts, destinationFacts);
			return equivalentDestinationInput || AlgebraEvaluationSafety.isPureRelational(leftCommon);
		}

		private void addOutputNames(Set<String> names, QueryAlgebraBindingAnalysis.OutputFacts facts) {
			names.addAll(facts.possibleOutputs());
			names.addAll(facts.guaranteedOutputs());
			names.addAll(facts.retainedInputNames());
		}

		private boolean equivalentFacts(QueryAlgebraBindingAnalysis.OutputFacts left,
				QueryAlgebraBindingAnalysis.OutputFacts right) {
			return left.possibleOutputsKnown() && left.guaranteedOutputsKnown()
					&& right.possibleOutputsKnown() && right.guaranteedOutputsKnown()
					&& left.possibleOutputs().equals(right.possibleOutputs())
					&& left.guaranteedOutputs().equals(right.guaranteedOutputs())
					&& left.fixedValues().equals(right.fixedValues())
					&& left.valueKinds().equals(right.valueKinds())
					&& left.retainedInputNames().equals(right.retainedInputNames())
					&& left.overwrittenInputNames().equals(right.overwrittenInputNames())
					&& left.canProduceRows() == right.canProduceRows();
		}
	}
}
